package com.sodi.metareports.user;
import com.sodi.metareports.role.repository.RoleRepository; import com.sodi.metareports.user.entity.AppUser; import com.sodi.metareports.user.repository.AppUserRepository;
import java.util.Set; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class InitialAdminInitializer implements ApplicationRunner { private static final Logger log=LoggerFactory.getLogger(InitialAdminInitializer.class); private final AppUserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; @Value("${app.security.password-min-length:12}") int passwordMinLength;
 @Value("${app.initial-admin.enabled:false}") boolean enabled; @Value("${app.initial-admin.username:}") String username; @Value("${app.initial-admin.email:}") String email; @Value("${app.initial-admin.password:}") String password; @Value("${app.initial-admin.first-name:}") String first; @Value("${app.initial-admin.last-name:}") String last;
 public InitialAdminInitializer(AppUserRepository u,RoleRepository r,PasswordEncoder e){users=u;roles=r;encoder=e;}
 @Override @Transactional public void run(ApplicationArguments args){if(!enabled||users.count()>0)return;if(username.isBlank()||email.isBlank()||first.isBlank()||last.isBlank()||password.length()<passwordMinLength)throw new IllegalStateException("Initial admin settings are incomplete or password is too short");AppUser u=new AppUser();u.setUsername(username.trim().toLowerCase());u.setEmail(email.trim().toLowerCase());u.setFirstName(first.trim());u.setLastName(last.trim());u.setPasswordHash(encoder.encode(password));u.setRoles(Set.of(roles.findByCode("SUPER_ADMIN").orElseThrow()));users.save(u);log.info("Initial administrator created");}}
